from pathlib import Path
import json
import numpy as np,pandas as pd
R=Path(__file__).resolve().parents[1]
def read(p):return json.loads((R/p).read_text())
def num(v):return 'NA' if v is None or not np.isfinite(v) else f'{v:.4f}'
def stat(z):return f"finite {z['finite_N']}/{z['frozen_N']}; rho={num(z['rho'])}, 95%CI {list(map(num,z['rho_CI95']))}; sign={num(z['proportion'])}, signed N={z['signed_N']}, 95%CI {list(map(num,z['sign_bootstrap_CI95']))}"
def main():
 execution=read('11_statistics/ANALYSIS_STATUS.json');assert not execution['counts'].get('MISSING',0),'Report cannot be finalized while inference jobs are unfinished'
 h=read('11_statistics/HARMONIZATION_AGREEMENT.json');route=read('13_manuscript_gate/FINAL_SCIENTIFIC_ROUTE.json');reference=read('11_statistics/REFERENCE_PERFORMANCE.json');gap=read('11_statistics/REFERENCE_OFFREF_GAP.json');gnrs=read('11_statistics/GNRS_RECOVERY_DIRECTION.json');coverage=read('08_truth_coverage/GNRS_COVERAGE_MECHANISMS.json');bound=read('08_truth_coverage/GNRS_ARCHITECTURAL_COVERAGE_UPPER_BOUND.json');external=read('08_truth_coverage/EXTERNAL_PUBLIC_TABLE_STATUS.json');member=read('03_within_model_ensembles/OFFICIAL_MEMBER_AVAILABILITY_FINAL.json');integrity=read('15_freeze/PREVIOUS_FREEZES_RECHECK.json');strata=read('11_statistics/OOD_STRATA.json');robust=read('11_statistics/PLACEMENT_AND_CONTEXT_AGREEMENT.json');pairs=read('11_statistics/ENSEMBLE_PAIRWISE_AGREEMENT.json')
 def within(model):
  z=[x for x in pairs if x['model']==model];return '; '.join(f"{x['memberA']} vs {x['memberB']}: "+stat(x) for x in z)
 def stability(model):
  d=pd.read_csv(R/'11_statistics'/f'{model}_ENSEMBLE_LOCUS_STABILITY.tsv',sep='\t');q=d[d.valid_members_N==4];return f'All four members finite {len(q)}/100; dominant sign median={num(q.dominant_sign_fraction.median())}; <1 fraction={num((q.dominant_sign_fraction<1).mean())}; missingness retained'
 robustness_records=robust
 def robust(model,kind):return '; '.join(str(x['alternative'])+'bp: '+stat(x) for x in robustness_records if x['model']==model and x['analysis']==kind)
 def stratum(variable,value):return stat(next(x for x in strata if x['variable']==variable and x['stratum']==value))
 strongest=route['strongest_uncertainty_supported_predictor'];predictor='No feature has BH q<0.05 with a bootstrap CI excluding zero' if strongest is None else json.dumps(strongest,ensure_ascii=False)
 rows=[('PHASE','PHASE1R3_MODEL_DISAGREEMENT_AND_OOD_AUDIT'),('FINAL VERDICT',route['FINAL_VERDICT']),('freeze integrity',json.dumps(integrity,ensure_ascii=False)),('frozen Class B core N','400; no failed locus replacement; 33GNRS and67extension remain separate'),('original cross-model rho',num(h['original']['rho'])),('harmonized-track rho',stat(h['tier1_cached'])),('original sign concordance',num(h['original']['proportion'])),('harmonized sign concordance',num(h['tier1_cached']['proportion'])),('Borzoi within-ensemble rho',within('Borzoi')),('Borzoi within-ensemble sign stability',stability('Borzoi')),('AlphaGenome within-ensemble availability',json.dumps(member['AlphaGenome'])+'; '+stability('AlphaGenome')),('placement robustness AG',robust('AlphaGenome','PLACEMENT')),('placement robustness Borzoi',robust('Borzoi','PLACEMENT')),('context robustness AG',robust('AlphaGenome','CONTEXT')),('context robustness Borzoi',robust('Borzoi','CONTEXT')+'; N-masked ablations inside524288 native input'),('non-repeat agreement',stratum('repeat_stratum','NON_REPEAT')),('SINE agreement',stratum('repeat_stratum','SINE/Alu')),('LINE agreement',stratum('repeat_stratum','LINE')),('LTR agreement',stratum('repeat_stratum','LTR')),('VNTR agreement',stratum('repeat_stratum','VNTR/STR')),('short-insertion agreement',stratum('length_bin','50–199')),('long-insertion agreement',stratum('length_bin','>5kb')+'; prospective bin actually ≥5000bp'),('strongest disagreement predictor',predictor),('reference benchmark N',f"Frozen500SNVs/473genes; joint finite {reference['strict_cross_model']['finite_N']}; jointly usable genes {gap['reference_genes_usable_N']}"),('reference benchmark cross-model rho',stat(reference['strict_cross_model'])),('reference benchmark sign concordance',num(reference['strict_cross_model']['proportion'])),('off-reference generalization gap',json.dumps(gap,ensure_ascii=False)),('GNRS recoverable N',f"Joint {gnrs['joint_recovered_N']}/33; {gnrs['coverage_verdict']}; original7unchanged"),('GNRS AlphaGenome direction',stat(gnrs['AlphaGenome'])),('GNRS Borzoi direction',stat(gnrs['Borzoi'])),('external QTL final availability',external['status']+f";13272association rows;1994anchor/length candidate rows across558ClassB loci;exact inserted-sequence identity and effect orientation unverified;93shared donors"),('recommended scientific route',route['FINAL_VERDICT']+';STOP beforePhase2')]
 assert len(rows)==32
 text=['# OFFREF-REG Phase1R3 final audit report','',f"Scientific route: **{route['FINAL_VERDICT']}**. Phase2 was not entered. Figures are rendered separately; final visual review and output hashing remain required until their audit records confirm completion.",'','| Item | Fixed summary | Observed result |','|---:|---|---|']
 for i,(label,value) in enumerate(rows,1):text.append(f'| {i} | {label} | {str(value).replace(chr(10)," ").replace("|",";")} |')
 text+=['','## Evidence and interpretation','',f"The original frozen core result remains {stat(h['original'])}. Exact-family rescoring uses the same complete strand-compatible GM12878 tracks and equal library-family weights. Its result is {stat(h['tier1_cached'])}. These diagnostics retain the original population and original scores.",'','Scale-only log1p sensitivity: '+stat(h['log1p'])+'. Original effects are retained.','','New official full-RNA outputs are reported separately: exact '+stat(h['TIER1_EXACT'])+'; near '+stat(h['TIER2_NEAR'])+'; global '+stat(h['TIER3_GLOBAL'])+'. Global pooling is tissue-unmatched and cannot establish tissue-specific calibration. Failed requests remain visible in the job audit; no subset is relabeled as all-track output.','',f"Original GNRS coverage: {json.dumps(coverage['primary_reasons'])}. Gene-preserving recovery retains all33locus/gene/insertion/beta identities. A recovered joint denominator below20 remains a low-coverage calibration result. Under the frozen gene annotation, even the union of every legal Borzoi placement can potentially reach only {bound['possibly_reachable_loci_upper_bound']}/33target genes; this is a relaxed geometry bound independent of RNA values. The original seven-locus directional analysis is unchanged.",'','Reference panel selection precedes prediction: eQTL Catalogue release7 GEUVADIS LCL, PIP≥0.9,500uniqueGRCh38-reference-checkedSNVs across473genes, maximum5variants per gene, deterministic hashed sampling. Prediction uses the same target-gene common-exon density and RNA tiers as OFFREF. The source is independent of model-based selection; GEUVADIS is not a donor-independent biological validation of GNRS. Gene-wise resampling handles repeated variants in reference genes. Effect class, ascertainment and genomic training/test overlap can affect the comparison.','', 'Reference measured-direction calibration: '+ '; '.join(m+': '+stat(reference[m+'_measured_beta']) for m in ['AlphaGenome','Borzoi'])+'. Gene-cluster sign-flip nulls and BH results are in the statistical source files. Cross-model agreement alone does not validate measured biological effects.','',f"Route gates: {json.dumps(route,ensure_ascii=False)}. Thresholds come from the prospective frozen protocol, rather than result-dependent tuning.",'','## External resource boundary','',f"[Supplementary Table4]({external['source_URL']}) is publicly accessible and contains slopes, genes and adjusted significance values. The13272rows are association rows, not13272distinctSVs. Anchor/length matching gives1994candidateassociation rows across558ClassB loci. These are not sequence-verified intersections. Table4 and the downloaded Methods do not explicitly establish effect-allele dosage orientation; the source also shares93donors with GNRS/MAGE. The table therefore supplies no newly verified independent signed truth in this audit. The one final targeted resource search has stopped. Optional1KCP access evidence is retained; no controlled individual data were acquired.",'','## Statistical and technical limits','', 'Within-model official members share model training structure; their dispersion is predictive instability, not biological replication. The same fixed100loci are used for member, placement and context analyses. Placement/context comparisons fix a common homologous exon intersection. AlphaGenome short inputs are native supported lengths; Borzoi short contexts are N-masked ablations within its mandatory524288bp input. No incomplete insertion is scored as a complete allele.','', 'Disagreement models use fixed L2logistic C1 and ridge alpha1 with2000paired-locus coefficient bootstraps. Sparse/constant features and rank deficiency are documented. CV is exploratory; coefficient bootstrap intervals are conditional on the fixed full-core scaling. P-values are descriptive bootstrap summaries with BH correction. No feature association establishes a biological mechanism. Pairwise agreement CIs use10000paired-locus bootstraps; reference CIs use gene clusters. Reference and core gap resampling uses independent deterministic streams.','', 'All ten figures include editable PDF/SVG,300dpiPNG and sourceTSV. Figure10 selects the four largest standardized discrepancies post hoc for illustration; it is not independent validation. Figure8 suppresses a directional-calibration scatter if jointGNRSN<20. Empty strata and missing outputs remain explicit.','', 'No provisional paper title or manuscript claims are released unless the scientific gate permits the OOD reliability audit route. No ORES or atlas construction was performed.']
 (R/'14_reports/PHASE1R3_FINAL_REPORT.md').write_text('\n'.join(text)+'\n');print('32_ITEM_REPORT_BUILT_PENDING_FINAL_QA_AND_FREEZE',flush=True)
if __name__=='__main__':main()
